class EnvironmentCommand{constructor(editor,before,after){this.editor=editor;this.before=clone(before);this.after=clone(after);this.affectsEnvironment=true}apply(v){this.editor.doc.environment=EnvironmentRules.normalize(v)}do(){this.apply(this.after)}undo(){this.apply(this.before)}}
class SettingsCommand{constructor(editor,before,after){this.editor=editor;this.before=before;this.after=after;this.affectsTerrain=before.theme!==after.theme||before.arenaLimit!==after.arenaLimit||JSON.stringify(before.terrain?.heightfield)!==JSON.stringify(after.terrain?.heightfield);this.affectsMaterial=JSON.stringify(before.terrain?.materials)!==JSON.stringify(after.terrain?.materials)}apply(s){const d=this.editor.doc;d.meta=clone(s.meta);d.theme=s.theme;d.arenaLimit=s.arenaLimit;d.minimapLimit=s.minimapLimit;d.terrainModifiers=clone(s.terrain.modifiers||[]);d.terrain=TerrainSurface.from(s.terrain.heightfield,s.arenaLimit);d.materials=MaterialSurface.from(s.terrain.materials,s.arenaLimit,d.terrain.size);if(s.environment)d.environment=EnvironmentRules.normalize(s.environment)}do(){this.apply(this.after)}undo(){this.apply(this.before)}}

