  for(const e of doc.elevation)if(['ramp','stairs'].includes(e.kind)&&e.rise/Math.max(1,e.d)>.6)push('warn',`${e.kind} is unusually steep.`,e.id);for(const l of doc.ladders){if(l.attached&&!doc.get(l.parentId))push('bad','An attached ladder has no valid parent.',l.id);const frame=canonicalLadderFrame(l.nx,l.nz,l.side),dot=frame.nx*num(l.tx)+frame.nz*num(l.tz),tLen=Math.hypot(num(l.tx),num(l.tz));if(Math.abs(num(l.nx)-frame.nx)>.001||Math.abs(num(l.nz)-frame.nz)>.001||Math.abs(num(l.tx)-frame.tx)>.001||Math.abs(num(l.tz)-frame.tz)>.001||Math.abs(dot)>.001||Math.abs(tLen-1)>.001)push('bad','Ladder orientation frame is invalid or incomplete.',l.id)};
