rotateSelected(delta){const objs=this.allSelected().filter(o=>['road','building','prop','elevation','spawn'].includes(o.type));if(!objs.length)return;const before=objs.map(clone),after=objs.map(clone),center=this.groupCenter(objs);for(const o of after){if(o.type!=='spawn')o.rot=normalizeRot(num(o.rot)+delta);else o.yaw=normalizeRot(o.yaw+delta);if(objs.length>1){const a=rad(delta),c=Math.cos(a),s=Math.sin(a),dx=o.x-center.x,dz=o.z-center.z;o.x=center.x+dx*c-dz*s;o.z=center.z+dx*s+dz*c}}this.commands.execute(new PatchCommand(this.doc,before,after,'Rotate'))}
