terrainLegendStats(){const L=Math.min(this.doc.arenaLimit,Math.max(30,this.doc.minimapLimit)),N=22,step=L*2/(N-1);let min=Infinity,max=-Infinity;for(let iz=0;iz<N;iz++)for(let ix=0;ix<N;ix++){const h=Resolver.terrainHeight(this.doc,-L+ix*step,-L+iz*step);min=Math.min(min,h);max=Math.max(max,h)}const lo=Number.isFinite(min)?min:0,hi=Number.isFinite(max)?max:0;return{min:lo,max:hi,range:hi-lo}}
