previewObject(o,moveId){if(!['building','prop','elevation','natural'].includes(o.type)){const d=new MapDocument(this.doc.serializeInternal());if(moveId)d.remove(moveId);d.add(clone(o));ModelRules.normalizeDocument(d);Resolver.resolve(d);const runtime=RuntimeCompiler.compile(d);return {geometry:runtime.geometry,parts:this.placementParts.call({doc:d,runtimePhysical:()=>runtime},[o],true)};}const raw=RuntimeCompiler.exportContract(this.doc),field=o.type==='building'?'buildings':o.type==='elevation'?'elevationObjects':o.type==='natural'?'naturalObstacles':'staticBoxes',list=o.type==='building'?this.doc.buildings:o.type==='elevation'?this.doc.elevation:o.type==='natural'?this.doc.naturals:this.doc.props,index=list.findIndex(x=>x.id===moveId),entry={...o,...(o.type==='natural'?{type:o.kind}:{})};if(index>=0)raw[field][index]=entry;else raw[field].push(entry);const geometry=createAuthoredWorldGeometry(sanitizeUploadedMapDefinition(raw)),i=index>=0?index:raw[field].length-1,parts=o.type==='building'?geometry.BUILDING_GEOMETRY[i].parts:o.type==='elevation'?geometry.ELEVATION_GEOMETRY[i].parts:o.type==='natural'?[geometry.NATURAL_PLAYER_COLLIDERS[i]].filter(Boolean):geometry.STATIC_GEOMETRY[i].parts;return {geometry,parts};}
